mapper.select:
SELECT SRVC_CD , COALESCE(NULLIF(WMS.FN_GET_SRVC_NM(SRVC_CD), ''), '') AS SRVC_NM , WH_CD , COALESCE(NULLIF(WMS.FN_GET_WH_NM(SRVC_CD, WH_CD), ''), '') AS WH_NM , VEHICLE_NO , DRV_NM , HP_NO , TON_CLS_CD , USE_YN , COALESCE(NULLIF(WMS.FN_GET_USER_NM(REG_ID), ''), '') AS REG_ID , TO_CHAR(REG_DATE, 'YYYY-MM-DD') AS REG_DATE , COALESCE(NULLIF(WMS.FN_GET_USER_NM(UPD_ID), ''), '') AS UPD_ID , TO_CHAR(UPD_DATE, 'YYYY-MM-DD') AS UPD_DATE FROM WMS.TB_VEHICLE WHERE 1 = 1 AND SRVC_CD = #{srvcCd} AND WH_CD = #{whCd}
AND VEHICLE_NO LIKE '%' || #{vehicleNo} || '%'
AND USE_YN = #{useYn}
ORDER BY VEHICLE_NO

mapper.delete:
DELETE 
  FROM WMS.TB_VEHICLE
 WHERE 1 = 1
   AND SRVC_CD = #{srvcCd}
   AND WH_CD = #{whCd}
   AND VEHICLE_NO IN

      #{vehicleNo}
